package io.rift.cronos;
import java.net.*;import java.io.*;import java.nio.charset.*;import java.util.*;import java.util.concurrent.*;
public class NativeReadHarness {
 static int count;interface Op{void run()throws Exception;}static void ok(boolean v){count++;if(!v)throw new AssertionError("check "+count);}static void bad(Op op)throws Exception{try{op.run();}catch(Exception e){count++;return;}throw new AssertionError("accepted "+count);}
 static String abi(byte[] bytes){StringBuilder s=new StringBuilder("0x");s.append(String.format("%064x",32)).append(String.format("%064x",bytes.length));for(byte b:bytes)s.append(String.format("%02x",b&255));while((s.length()-2)%64!=0)s.append('0');return s.toString();}
 public static void main(String[] args)throws Exception{
  ok(ReadPolicy.address("0x"+"A".repeat(40)).equals("0x"+"a".repeat(40)));bad(()->ReadPolicy.address("bad"));ok(ReadPolicy.token("00001").equals("1"));bad(()->ReadPolicy.token(java.math.BigInteger.ONE.shiftLeft(256).toString()));bad(()->ReadPolicy.hash("0x1"));ok(ReadPolicy.hash("0x"+"A".repeat(64)).endsWith("a"));for(String op:new String[]{"status","balance","nft","tokenUri","receipt","observations","metadata"})ok(ReadPolicy.operation(op).equals(op));for(String op:new String[]{"eth_sendTransaction","eth_call","sign","fetch","setKey","schedule"})bad(()->ReadPolicy.operation(op));bad(()->ReadPolicy.standard("ERC-20"));
  String uri="data:application/json,{\"name\":\"Original artwork\"}";ok(AbiString.decode(abi(uri.getBytes(StandardCharsets.UTF_8))).equals(uri));ok(AbiString.decode(abi(new byte[0])).isEmpty());bad(()->AbiString.decode("0x"));bad(()->AbiString.decode(abi(new byte[]{(byte)0xc0,(byte)0x80})));bad(()->AbiString.decode(abi(new byte[16385])));String wrong=abi(new byte[]{1});bad(()->AbiString.decode(wrong.substring(0,wrong.length()-1)+"1"));bad(()->AbiString.decode("0x"+"0".repeat(64)+wrong.substring(66)));
  ok(!WatchPolicy.expired(100,101,0));ok(WatchPolicy.expired(100,99,0));ok(WatchPolicy.expired(100,100+WatchPolicy.MAX_AGE,0));ok(WatchPolicy.expired(100,101,96));ok(WatchPolicy.next(100,1,true)==100+WatchPolicy.INTERVAL);ok(WatchPolicy.next(100,2,true)==100+2*WatchPolicy.INTERVAL);ok(WatchPolicy.next(100,96,true)==100+6*60*60*1000L);ok(WatchPolicy.next(100,96,false)==100+WatchPolicy.INTERVAL);bad(()->WatchPolicy.next(Long.MAX_VALUE,1,true));
  RequestControl cancelled=new RequestControl(1000);Socket socket=new Socket();cancelled.socket(socket);cancelled.close();ok(socket.isClosed());bad(()->cancelled.remaining(100));RequestControl expired=new RequestControl(1);Thread.sleep(5);bad(()->expired.remaining(100));
  CountDownLatch entered=new CountDownLatch(2),release=new CountDownLatch(1);BoundedDns dns=new BoundedDns(host->{entered.countDown();while(release.getCount()>0)try{release.await();}catch(InterruptedException ignored){}return new InetAddress[]{InetAddress.getByAddress(new byte[]{8,8,8,8})};});ExecutorService callers=Executors.newFixedThreadPool(2);
  try{Callable<Boolean> call=()->{try(RequestControl c=new RequestControl(1000)){try{dns.resolve("fixture.invalid",c);return false;}catch(IOException expected){return true;}}};Future<Boolean> first=callers.submit(call),second=callers.submit(call);ok(entered.await(5,TimeUnit.SECONDS));ok(first.get(5,TimeUnit.SECONDS));ok(second.get(5,TimeUnit.SECONDS));try(RequestControl c=new RequestControl(100)){bad(()->dns.resolve("fixture.invalid",c));}}finally{release.countDown();dns.close();callers.shutdownNow();}
  System.out.println("Native read/deadline/watch assertions passed: "+count);
 }
}
